from __future__ import annotations
from dataclasses import dataclass
from typing import List, Set, Tuple

@dataclass(frozen=True)
class Form:
    kind: str
    index: int = 0
    left: 'Form | None' = None
    right: 'Form | None' = None

@dataclass
class Frame:
    worlds: List[int]
    R: Set[Tuple[int, int]]
    def successors(self, w: int) -> List[int]:
        return [v for v in self.worlds if (w, v) in self.R]

def sat(frame: Frame, w: int, phi: Form) -> bool:
    if phi.kind == 'bot':
        return False
    if phi.kind == 'imp':
        return (not sat(frame, w, phi.left)) or sat(frame, w, phi.right)
    if phi.kind == 'neg':
        return not sat(frame, w, phi.left)
    if phi.kind == 'box':
        return all(sat(frame, v, phi.left) for v in frame.successors(w))
    raise ValueError(phi.kind)

def valid(frame: Frame, phi: Form) -> bool:
    return all(sat(frame, w, phi) for w in frame.worlds)

from __future__ import annotations
from typing import List, Set, Tuple

def con_status(worlds: List[int], R: Set[Tuple[int, int]]) -> str:
    """Classify the consistency sentence on a finite GL frame."""
    con_true = 0
    con_false = 0
    for w in worlds:
        terminal = not any((w, v) in R for v in worlds)
        # box bot is true iff w is terminal; Con = box bot -> bot.
        if terminal:
            con_false += 1
        else:
            con_true += 1
    if con_false == 0:
        return 'PROVABLE'
    if con_true == 0:
        return 'REFUTABLE'
    return 'INDEPENDENT'

if __name__ == '__main__':
    # standard frame: 1 -> 0, world 0 terminal, world 1 internal
    print(con_status([0, 1], {(1, 0)}))   # INDEPENDENT

